def _check():
    bad = set(';{}|')
    for k, v in FORMS.items():
        assert len(v) == 8, k
        for i, s in enumerate(v[1:], 1):
            items = [x.strip() for x in s.split(';')]
            assert 8 <= len(items) <= 10, (k, i, len(items))
            for it in items:
                assert it and '{' not in it and '}' not in it and '|' not in it, (k, it)
                assert ': ' not in it, (k, it)
    for k, s in SHARED.items():
        items = [x.strip() for x in s.split(';')]
        assert 10 <= len(items) <= 12, (k, len(items))
        for it in items:
            assert '{' not in it and '}' not in it and '|' not in it and ': ' not in it, (k, it)


if __name__ == '__main__':
    _check()
    assert set(DISPLAY) == set(FORMS)
    for _k, _s in DISPLAY.items():
        _it = [x.strip() for x in _s.split(';')]
        assert 6 <= len(_it) <= 8, _k
        assert not any(c in x for x in _it for c in '{}|') and not any(': ' in x for x in _it), _k
    print('forms', len(FORMS))
    for k, v in FORMS.items():
        print(k, [len(s.split(';')) for s in v[1:]])
    for k, s in SHARED.items():
        print(k, len(s.split(';')))
